import{_ as u,a0 as r,w as a,s as i,ao as l,I as p,x as o,a1 as n,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const c=JSON.parse('{"title":"如何在Ubuntu中屏蔽一個網站 | LCTT x X-CMD","titleTemplate":false,"description":"如何在Ubuntu中屏蔽一個網站 | LCTT (201403) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在Ubuntu中屏蔽一個網站 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在Ubuntu中屏蔽一個網站 | LCTT (201403) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201403/How To Block A Website In Ubuntu","title":"如何在Ubuntu中屏蔽一個網站","tag":"201403","desc":""},"relativePath":"201403/How To Block A Website In Ubuntu.md","filePath":"[post].md"}'),b={name:"201403/How To Block A Website In Ubuntu.md"};function m(d,t,T,g,f,x){const e=r("Link");return a(),i("div",null,[t[11]||(t[11]=l(`<h1 id="如何在ubuntu中屏蔽一個網站" tabindex="-1">如何在Ubuntu中屏蔽一個網站 <a class="header-anchor" href="#如何在ubuntu中屏蔽一個網站" aria-label="Permalink to “如何在Ubuntu中屏蔽一個網站”">​</a></h1><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/02/block-websites.jpg" alt=""></p><p>親愛的<strong>ubuntu</strong>極客們，</p><p>在本教程中我將教你如何通過編輯<strong>/etc/hosts</strong>文件來屏蔽在Ubuntu Linux上不受歡迎的網站，這是用來處理DNS和Linux網絡的系統文件。</p><p>我很喜歡這種方法，因為我不需要依靠第三方應用程序，這是非常容易使用的。您需要做的就是在<strong>/etc/hosts文件</strong>文件中做一個簡單的變化。</p><p>請確保您有使用此方法時在機器上處於root用户訪問狀態，因為<strong>/etc/hosts文件</strong>文件由root用户擁有的，所以它不能被不被普通用户編輯。</p><p>編輯 <strong>/etc/hosts</strong> 文件您需要什麼？root權限和一個文本編輯器。</p><p>在本教程中我將用我喜歡的文本編輯器，vim。好了，打開一個新的終端（<strong>CTRL+ALT+T</strong>），然後運行下面的命令來打開/etc/hosts文件進行編輯。</p><pre><code>vim /etc/hosts
</code></pre><p>添加下面這行</p><pre><code>127.0.0.1   domain.com
</code></pre><p>更換domain.com為你要屏蔽的網站，你完成了編輯處理後，保存該文件並退出。</p><p>現在是時候來測試該方法是否成功了。嘗試訪問你屏蔽的網站。</p><p>我的表弟是沉迷於Facebook的社交網絡，每次他發現我的筆記本電腦的時候，他就打開它，並去facebook.com陪陪他的朋友。</p><p>我應該怎麼做呢？</p><p>我編輯<strong>/etc/hosts</strong>文件，這樣他想訪問的網站就像已關閉了一樣。</p><p>您也可以使用這個方法來保護孩子免受互聯網成人內容的危害，如色情和恐怖電影。</p><hr>`,18)),p("p",null,[t[1]||(t[1]=o("via: ",-1)),n(e,{href:"http://www.unixmen.com/block-website-ubuntu/"},{default:s(()=>[...t[0]||(t[0]=[o("http://www.unixmen.com/block-website-ubuntu/",-1)])]),_:1})]),p("p",null,[t[4]||(t[4]=o("譯者：",-1)),n(e,{href:"https://github.com/yechunxiao19"},{default:s(()=>[...t[2]||(t[2]=[o("烏龍茶",-1)])]),_:1}),t[5]||(t[5]=o(" 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:s(()=>[...t[3]||(t[3]=[o("wxy",-1)])]),_:1})]),p("p",null,[t[8]||(t[8]=o("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[6]||(t[6]=[o("LCTT",-1)])]),_:1}),t[9]||(t[9]=o(" 原創翻譯，",-1)),n(e,{href:"http://linux.cn/"},{default:s(()=>[...t[7]||(t[7]=[o("Linux中國",-1)])]),_:1}),t[10]||(t[10]=o(" 榮譽推出",-1))])])}const k=u(b,[["render",m]]);export{c as __pageData,k as default};
